-- Shared demo sandbox for PolyBot Terminal. Generated by scripts/gen-supabase-schema.mjs
-- from base44/entities/*.jsonc. Edit the entity files and rerun; hand-written parts are
-- below the generated tables.

create extension if not exists pgcrypto;

create or replace function public.set_updated_date() returns trigger language plpgsql as $$
begin
  new.updated_date := now();
  return new;
end $$;

create table if not exists public.bot_runs (
  "id" uuid primary key default gen_random_uuid(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "name" text, -- Bot run name/identifier
  "algorithm" text, -- Trading algorithm used; copy = mirror the wallets in copy_wallets
  "categories" jsonb, -- Market categories targeted (app category ids, mapped to Polymarket tags)
  "fund_allocation" double precision, -- USDC amount allocated
  "duration_hours" double precision, -- Planned duration in hours
  "status" text default 'running',
  "is_paper" boolean default false, -- If true, this is a paper trading experiment (no real funds)
  "fill_mode" text, -- paper = experiment; simulated = live bot without a connected signer; live = real orders
  "current_value" double precision, -- Current portfolio value for this run (allocation + realized + unrealized)
  "pnl" double precision, -- Profit/Loss amount
  "pnl_percent" double precision, -- Profit/Loss percentage
  "realized_pnl" double precision, -- P&L from closed positions
  "unrealized_pnl" double precision, -- Mark-to-market P&L of open positions (marked at the bid)
  "positions_bought" double precision default 0,
  "positions_sold" double precision default 0,
  "open_positions" double precision default 0,
  "start_time" timestamptz,
  "end_time" timestamptz,
  "custom_params" jsonb, -- Custom algorithm parameters: entry, exit (YES price thresholds), maxPositions
  "pnl_history" jsonb, -- P&L points { time, pnl, value }, one per engine tick
  "activity_log" jsonb, -- Engine log lines { t, type, msg } (last 150)
  "kelly_fraction" double precision default 0.25, -- Kelly fraction used for sizing (e.g. 0.25 = quarter-Kelly)
  "order_type" text default 'GTC', -- CLOB order type
  "neg_risk" boolean default false, -- Whether this bot trades NegRisk multi-outcome markets
  "max_positions" double precision, -- Maximum concurrent open positions
  "stop_loss_pct" double precision, -- Close a position when it is down this % of its cost
  "take_profit_pct" double precision, -- Close a position when it is up this % of its cost
  "max_position_pct" double precision, -- Max % of the allocation in one position
  "vpin" double precision, -- Latest VPIN reading (toxic flow indicator, 0-1)
  "avg_edge" double precision, -- Average estimated edge % at entry across all trades in this run
  "markets_scanned" double precision, -- Markets in the universe on the last tick
  "ticks" double precision default 0, -- Engine ticks run so far
  "last_tick_at" timestamptz, -- When the engine last processed this bot (browser or backend)
  "last_error" text, -- Last engine error, cleared on the next good tick
  "entry_cooldowns" jsonb, -- conditionId → ISO time until which the bot will not re-enter that market
  "engine_version" text,
  "copy_wallets" jsonb, -- Copy bots: pilots to mirror [{ address, name, profileImage }]
  "copy_mode" text default 'mirror', -- mirror = buy into the pilot's current book at launch; new_only = copy moves made after launch
  "copy_state" jsonb, -- Copy bots: last snapshot per pilot { address: { positions: { tokenId: shares }, value, syncedAt } }
  "server_tick" boolean default true, -- Let the scheduled backend function tick this bot when no browser is open
  "_" boolean -- trailing column keeps the generated list simple; unused
);
alter table public.bot_runs drop column if exists "_";
create trigger bot_runs_updated before update on public.bot_runs for each row execute function public.set_updated_date();

create table if not exists public.trades (
  "id" uuid primary key default gen_random_uuid(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "bot_run_id" text, -- Associated bot run ID
  "market_name" text, -- Market question
  "market_id" text, -- Polymarket condition ID
  "gamma_market_id" text, -- Gamma API market id
  "token_id" text, -- CLOB token id of the outcome held
  "event_title" text,
  "event_slug" text,
  "market_slug" text,
  "market_url" text, -- Link to the market on polymarket.com
  "side" text,
  "outcome" text, -- YES or NO token traded
  "entry_price" double precision,
  "exit_price" double precision,
  "current_price" double precision, -- Latest mark (bid) while open
  "quantity" double precision, -- Shares
  "size_usdc" double precision, -- Cost at entry
  "pnl" double precision, -- Realized P&L once closed
  "unrealized_pnl" double precision,
  "status" text default 'open',
  "timestamp" timestamptz,
  "exit_time" timestamptz,
  "exit_reason" text,
  "order_type" text default 'GTC',
  "edge_at_entry" double precision, -- Estimated edge (%) at time of entry vs market price
  "est_prob" double precision, -- Strategy's estimated win probability at entry
  "kelly_fraction" double precision, -- Kelly fraction applied to this trade
  "neg_risk" boolean default false,
  "fill_mode" text, -- paper | simulated | live, with a -maker suffix for passive fills
  "strategy" text,
  "signal" text, -- Signal id that opened the position
  "signal_value" double precision, -- Signal magnitude at entry (price move, imbalance, spread, edge)
  "signal_reason" text, -- Human-readable reason for the entry
  "pilot_address" text, -- Copy bots: the wallet this lot mirrors
  "outcome_label" text, -- Outcome name as Polymarket shows it (team name, candidate, …)
  "basket_id" text, -- Groups the legs of an arbitrage basket
  "basket_payout" double precision, -- Guaranteed payout per set for a basket leg
  "_" boolean -- trailing column keeps the generated list simple; unused
);
alter table public.trades drop column if exists "_";
create trigger trades_updated before update on public.trades for each row execute function public.set_updated_date();

create table if not exists public.whale_signals (
  "id" uuid primary key default gen_random_uuid(),
  "created_date" timestamptz not null default now(),
  "updated_date" timestamptz not null default now(),
  "created_by" text,
  "trade_id" text, -- Stable fill id: txHash:tokenId:side:size (dedupe key)
  "tx_hash" text,
  "traded_at" timestamptz, -- When the fill happened on chain
  "wallet" text, -- Polymarket proxy wallet (lower-case 0x address)
  "trader_name" text,
  "profile_image" text,
  "side" text,
  "outcome" text,
  "outcome_index" double precision,
  "condition_id" text,
  "title" text,
  "event_slug" text,
  "icon" text,
  "category" text, -- App category from the market's Gamma tags (politics, sports, …, other)
  "price" double precision,
  "size" double precision, -- Shares
  "usd" double precision, -- Notional: shares × price
  "kinds" jsonb, -- Why the fill was stored
  "flags" jsonb, -- Insider flag ids (fresh_account, few_markets, concentrated, long_shot, big_size)
  "insider_score" double precision,
  "suspicious" boolean,
  "wallet_age_days" double precision,
  "wallet_markets" double precision,
  "wallet_pnl" double precision, -- Wallet's all-time P&L at scan time
  "portfolio_value" double precision,
  "_" boolean -- trailing column keeps the generated list simple; unused
);
alter table public.whale_signals drop column if exists "_";
create trigger whale_signals_updated before update on public.whale_signals for each row execute function public.set_updated_date();

-- ─── Indexes ────────────────────────────────────────────────────────────────
create index if not exists bot_runs_status_idx on public.bot_runs ("status");
create index if not exists bot_runs_created_idx on public.bot_runs ("created_date" desc);
create index if not exists trades_bot_status_idx on public.trades ("bot_run_id", "status");
create index if not exists trades_created_idx on public.trades ("created_date" desc);
create unique index if not exists whale_signals_trade_idx on public.whale_signals ("trade_id");
create index if not exists whale_signals_traded_idx on public.whale_signals ("traded_at" desc);

-- ─── Sandbox metadata (one row) ─────────────────────────────────────────────
create table if not exists public.demo_meta (
  id int primary key,
  created_at timestamptz not null default now(),
  last_reset_at timestamptz not null default now(),
  resets_at timestamptz not null default now() + interval '2 hours',
  reset_every interval not null default interval '2 hours',
  last_tick_at timestamptz
);
insert into public.demo_meta (id) values (1) on conflict (id) do nothing;

-- ─── Guard rails for a public sandbox ───────────────────────────────────────
-- Anyone can start a paper portfolio. Keep it small: 20 active portfolios at a time,
-- paper amounts between $1 and $10,000, short names.
create or replace function public.bot_runs_guard() returns trigger language plpgsql as $$
declare active_count int;
begin
  select count(*) into active_count from public.bot_runs where "status" in ('running', 'paused');
  if active_count >= 20 then
    raise exception 'The sandbox is full (20 running portfolios). It resets on the next schedule.';
  end if;
  if new."fund_allocation" is null or new."fund_allocation" < 1 or new."fund_allocation" > 10000 then
    raise exception 'Paper amounts in the sandbox are between $1 and $10,000.';
  end if;
  if new."is_paper" is distinct from true then
    new."is_paper" := true;
    new."fill_mode" := 'paper';
  end if;
  new."name" := left(coalesce(new."name", 'portfolio'), 60);
  return new;
end $$;
drop trigger if exists bot_runs_guard on public.bot_runs;
create trigger bot_runs_guard before insert on public.bot_runs for each row execute function public.bot_runs_guard();

-- ─── Reset: wipe everything, the next tick re-seeds the sample portfolios ───
create or replace function public.demo_reset() returns void language plpgsql security definer set search_path = public as $$
begin
  truncate table public.trades, public.bot_runs;
  update public.demo_meta set last_reset_at = now(), resets_at = now() + reset_every where id = 1;
end $$;
revoke all on function public.demo_reset() from public, anon, authenticated;

-- ─── Row-level security: the browser (anon key) reads, creates and updates; never deletes ──
alter table public.bot_runs enable row level security;
alter table public.trades enable row level security;
alter table public.whale_signals enable row level security;
alter table public.demo_meta enable row level security;

drop policy if exists "sandbox read" on public.bot_runs;
drop policy if exists "sandbox insert" on public.bot_runs;
drop policy if exists "sandbox update" on public.bot_runs;
create policy "sandbox read" on public.bot_runs for select to anon, authenticated using (true);
create policy "sandbox insert" on public.bot_runs for insert to anon, authenticated with check (true);
create policy "sandbox update" on public.bot_runs for update to anon, authenticated using (true) with check (true);

drop policy if exists "sandbox read" on public.trades;
drop policy if exists "sandbox insert" on public.trades;
drop policy if exists "sandbox update" on public.trades;
create policy "sandbox read" on public.trades for select to anon, authenticated using (true);
create policy "sandbox insert" on public.trades for insert to anon, authenticated with check (true);
create policy "sandbox update" on public.trades for update to anon, authenticated using (true) with check (true);

drop policy if exists "signals read" on public.whale_signals;
create policy "signals read" on public.whale_signals for select to anon, authenticated using (true);

drop policy if exists "meta read" on public.demo_meta;
create policy "meta read" on public.demo_meta for select to anon, authenticated using (true);

grant usage on schema public to anon, authenticated;
grant select, insert, update on public.bot_runs, public.trades to anon, authenticated;
grant select on public.whale_signals, public.demo_meta to anon, authenticated;
